@RestController
@RequestMapping("/api/users")
public class UserController {
    @PutMapping("/{id}")
    public ResponseEntity<User> replaceUser(@PathVariable Long id, @RequestBody User user) {
        // PUT: Replace entire entity
        return ResponseEntity.ok(service.updateFull(id, user));
    }

    @PatchMapping("/{id}")
    public ResponseEntity<User> patchUser(@PathVariable Long id, @RequestBody Map<String, Object> updates) {
        // PATCH: Partial update using Map or DTO
        return ResponseEntity.ok(service.patch(id, updates));
    }
}
